UPDATE EARNINGS_AGENT_RUN
SET fiscal_quarter = #{fiscalQuarter}, status = #{status}, current_round = #{currentRound},
    step_count = #{stepCount}, llm_call_count = #{llmCallCount}, confidence = #{confidence},
    end_time = #{endTime}, state_json = #{stateJson}, final_result = #{finalResult},
    error_message = #{errorMessage}
WHERE run_id = #{runId}
